<?php
declare(strict_types=1);namespace App\Interfaces\Http\Controllers\Api\V1\Policies;
use App\Application\Policies\RenewalService;use App\Domain\Tenancy\TenantContext;use App\Models\{Policy,RenewalCase,Tenant};use Illuminate\Http\{JsonResponse,Request};
final class RenewalController{private function scoped(string$id):RenewalCase{return RenewalCase::where('tenant_id',app(TenantContext::class)->id())->findOrFail($id);}public function seed(Request$r,RenewalService$s,TenantContext$c):JsonResponse{$d=$r->validate(['days'=>'required|integer|min:1|max:180']);return response()->json(['data'=>['created_or_found'=>$s->seed(Tenant::findOrFail($c->id()),$d['days'],$r->user())]]);}public function createQuote(Request$r,string$renewal,RenewalService$s):JsonResponse{return response()->json(['data'=>$s->createQuote($this->scoped($renewal),$r->user())],201);}public function complete(Request$r,string$renewal,RenewalService$s):JsonResponse{$d=$r->validate(['successor_policy_id'=>'required|uuid|exists:policies,id']);$p=Policy::where('tenant_id',app(TenantContext::class)->id())->findOrFail($d['successor_policy_id']);return response()->json(['data'=>$s->complete($this->scoped($renewal),$p)]);}}
